SELECT ID, PARTY_NAME, ORG_IDENTITY, ATTRIBUTE_02, ATTRIBUTE_03,
    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD') AS CREATED_DATE
FROM PARTY_ORGANIZATION WHERE 
AND ORG_IDENTITY = #{orgIdentity}
AND ID = #{partyId}
ORDER BY TREE_SORTS, TREE_SORT, ID

SELECT ID, PARTY_ID, NF FROM DYN_ZTDR WHERE TRIM(NF) = #{year} AND PARTY_ID IN
#{id}
ORDER BY ID
